func:
if (msg.topic === 'form/submit') {
    var rayvn = {
        payload: {
            rayvn_api_key: msg.payload.rayvn_api_key,
            rayvn_log_name: msg.payload.rayvn_log_name
        }
    };

    var wasos = {
        payload: {
            wasos_username: msg.payload.wasos_username,
            wasos_password: msg.payload.wasos_password,
            wasos_chatroom_name: msg.payload.wasos_chatroom_name
        }
    };

    return [rayvn, wasos, null, null, null];
}

if (msg.topic === 'connection/toggle') {
    return [null, null, msg, null, null];
}

if (msg.topic === 'connection/remove') {
    return [null, null, null, msg, null];
}

if (msg.topic === 'connection/boost') {
    return [null, null, null, null, msg];
}    

return [null, null, null, null, null];

const { name, active } = msg.payload;
const path = 'parat_bridge.connections.' + name + '.active';
global.set(path, active);
return null;

var connections = global.get('parat_bridge.connections') || {};
msg = {
    topic: 'connections/update',
    payload: connections
};
return msg;

const { name } = msg.payload;

if (!global.get('parat_bridge.connections.' + name)) return null;

global.set('parat_bridge.connections.' + name, null);

return null;

const { name, enabled } = msg.payload;

if (!global.get('parat_bridge.connections.' + name)) return null;

global.set('parat_bridge.connections.' + name + '.boost_mode', enabled);

const connections = global.get('parat_bridge.connections') || {};
const anyBoost = Object.values(connections).some(c => c.boost_mode === true);
global.set('parat_bridge.boost_mode', anyBoost);

node.status({
    fill: enabled ? 'green' : 'grey',
    shape: 'dot',
    text: name + ' boost ' + (enabled ? 'ON' : 'OFF')
        + ' ' + new Date().toLocaleTimeString()
});

return null;
